#!/usr/bin/env bun
// @bun
var CINEMA_ID="0000000002";var BASE_URL="https://www.classiccinemas.com.au/api";var AEST_OFFSET_MS=10*60*60*1000;async function fetchJson(url,destPath){const resp=await fetch(url);if(!resp.ok){throw new Error(`GET ${url} failed: ${resp.status} ${resp.statusText}`)}const text=await resp.text();if(destPath){await Bun.write(destPath,text)}return JSON.parse(text)}async function readOrFetchJson(path,url){const file=Bun.file(path);if(await file.exists()){return JSON.parse(await file.text())}return fetchJson(url,path)}function seatmapTmpPath(sessionId){return`/tmp/cc-seatmap-${sessionId}.json`}function seatmapUrl(sessionId){return`${BASE_URL}/sessions/${CINEMA_ID}/${sessionId}/seating-map`}function formatTime(isoStr){const timePart=isoStr.split("T")[1]??"";const[hStr="0",mStr="0"]=timePart.split(":");let hours=Number.parseInt(hStr,10);const minutes=Number.parseInt(mStr,10);const ampm=hours>=12?"pm":"am";hours=hours%12;if(hours===0)hours=12;const mm=minutes.toString().padStart(2,"0");return`${hours}:${mm}${ampm}`}function todayAest(){const now=new Date;const local=new Date(now.getTime()+AEST_OFFSET_MS);return local.toISOString().slice(0,10)}function maybeExitWithHelp(arg,help){if(arg==="-h"||arg==="--help"){console.log(help);process.exit(0)}}function runMain(main){main().catch((err)=>{console.error(err instanceof Error?err.message:String(err));process.exit(1)})}var SLOT_ORDER=["Adult","Child","Concession","Senior","Student","Pension"];var TICKETS_TMP="/tmp/cc-tickets.json";var SELECTED_TMP="/tmp/cc-tickets-selected.json";var HELP=`classic-cinema parse-tickets \u2014 price a ticket spec, write selection file

Usage:
  bun run src/parse-tickets.ts --session-id 122890 --spec "1+1"

Options:
  --session-id ID   Session id for ticket fetch (required)
  --spec SPEC       Positional ticket spec, e.g. "1+1" (required)
  -h, --help        Show this help

Slots: Adult+Child+Concession+Senior+Student+Pension.
Output: one JSON object on stdout. Diagnostics on stderr.
Exit: 0 ok, 1 unavailable/invalid, 64 invalid usage.`;function formatPrice(cents){return`$${(cents/100).toFixed(2)}`}function parseSpec(specStr){const parts=specStr.trim().split("+");const result=[];for(let i=0;i<parts.length;i++){const raw=parts[i].trim();const qty=Number.parseInt(raw,10);if(!/^\d+$/.test(raw)||Number.isNaN(qty)){console.error(`Invalid spec part: '${parts[i]}' \u2014 expected a number`);process.exit(1)}if(i>=SLOT_ORDER.length){console.error(`Too many ticket slots (max ${SLOT_ORDER.length})`);process.exit(1)}if(qty>0)result.push([SLOT_ORDER[i],qty])}return result}function parseArgs(argv){let sessionId=null;let spec=null;for(let i=0;i<argv.length;i++){const arg=argv[i];maybeExitWithHelp(arg,HELP);if(arg==="--session-id"){sessionId=argv[++i]??""}else if(arg.startsWith("--session-id=")){sessionId=arg.slice("--session-id=".length)}else if(arg==="--spec"){spec=argv[++i]??""}else if(arg.startsWith("--spec=")){spec=arg.slice("--spec=".length)}else{console.error(`Unknown argument: ${arg}`);console.error(HELP);process.exit(64)}}if(sessionId===null||spec===null){console.error("Missing required --session-id and/or --spec");console.error(HELP);process.exit(64)}return{sessionId,spec}}async function main(){const{sessionId,spec}=parseArgs(process.argv.slice(2));let data;try{data=await readOrFetchJson(TICKETS_TMP,`${BASE_URL}/sessions/${CINEMA_ID}/${sessionId}/tickets`)}catch(err){const msg=err instanceof Error?err.message:String(err);console.error(`Failed to fetch tickets: ${msg}`);process.exit(1)}const typeLookup=new Map;for(const t of data.ticketTypes??[]){if(t.categoryId===2)typeLookup.set(t.name,t)}const selections=parseSpec(spec);if(selections.length===0){console.error("No tickets in spec");process.exit(1)}const tickets=[];let totalCents=0;let totalFeeCents=0;const summaryParts=[];for(const[typeName,qty]of selections){const tt=typeLookup.get(typeName);if(!tt){const available=[...typeLookup.keys()].sort();console.error(`Ticket type '${typeName}' not available for this session. `+`Available types: ${available.length?available.join(", "):"(none)"}`);process.exit(1)}tickets.push({type:typeName,qty,price:tt.priceInCents});const lineTotal=tt.priceInCents*qty;totalCents+=lineTotal;totalFeeCents+=tt.bookingFeeInCents*qty;summaryParts.push(`${qty}x ${typeName} (${formatPrice(lineTotal)})`)}const grandTotal=totalCents+totalFeeCents;summaryParts.push(`fees (${formatPrice(totalFeeCents)})`);const summary=`${summaryParts.join(" + ")} = ${formatPrice(grandTotal)}`;await Bun.write(SELECTED_TMP,`${JSON.stringify(tickets,null,2)}
`);console.log(JSON.stringify({tickets,bookingFeeCents:totalFeeCents,totalCents:grandTotal,summary,selectedFile:SELECTED_TMP}))}if(import.meta.main){runMain(main)}
